/* Alert queue and triage. Alerts are generated by the rule engine from the enabled rules. */
(function () {
  'use strict';
  const { S, BY, esc, hms, full, go, act, chg, inp, toast, flyout, render, alertState, setAlertState, docId, MITRE } = App;
  S.al = { sel: new Set(), search: '', checked: false };
  const STAT = ['open', 'acknowledged', 'closed'];
  const CLS = [['', 'Unclassified'], ['true-positive', 'True positive'], ['false-positive', 'False positive'], ['benign', 'Benign, expected']];
  const clsLabel = c => (CLS.find(x => x[0] === c) || CLS[0])[1];

  function list() {
    const p = S.params;
    let a = App.rangedAlerts();
    if (p.sev) a = a.filter(x => x.severity === p.sev);
    if (p.status) a = a.filter(x => alertState(x.id).status === p.status);
    if (p.rule) a = a.filter(x => x.ruleId === p.rule);
    if (p.tech) a = a.filter(x => x.mitre.includes(p.tech));
    if (p.cls) a = a.filter(x => (alertState(x.id).classification || 'none') === p.cls);
    const t = S.al.search.toLowerCase();
    if (t) a = a.filter(x => `${x.ruleName} ${x.entity} ${x.reason}`.toLowerCase().includes(t));
    return a;
  }
  // A false-positive classification and "benign, expected" both mean no threat here.
  const correct = (a, c) => (a.truth === 'false-positive' ? c === 'false-positive' || c === 'benign' : c === 'true-positive');
  function score() {
    const done = S.alerts.filter(a => alertState(a.id).classification);
    return { done: done.length, right: done.filter(a => correct(a, alertState(a.id).classification)).length, total: S.alerts.length };
  }
  const select = (id, label, opts, val) => `<label class="small muted">${label} <select data-chg="alFilter" data-k="${id}">${opts.map(([v, l]) => `<option value="${esc(v)}" ${v === (val || '') ? 'selected' : ''}>${esc(l)}</option>`).join('')}</select></label>`;

  S.views.alerts = {
    render() {
      const p = S.params, rows = list(), all = App.rangedAlerts(), sc = score();
      const cnt = s => all.filter(a => alertState(a.id).status === s).length;
      const body = rows.map(a => {
        const st = alertState(a.id);
        return `<tr class="click" data-act="showAlert" data-id="${esc(a.id)}"><td><input type="checkbox" data-chg="alSel" data-id="${esc(a.id)}" aria-label="Select alert" ${S.al.sel.has(a.id) ? 'checked' : ''}></td><td class="mono small">${hms(a.t)}</td><td>${esc(a.ruleName)}</td><td class="sev ${a.severity}">${esc(a.severity)}</td><td class="mono small">${esc(a.entity)}</td><td class="small">${esc(a.reason)}</td><td class="st-${st.status}">${esc(st.status)}</td><td class="small">${esc(st.assignee || '–')}</td><td class="small">${esc(st.classification ? clsLabel(st.classification) : '–')}</td>${S.answers ? `<td class="small ${a.truth === 'false-positive' ? 'vm' : 'vh'}">${a.truth === 'false-positive' ? 'FP' : 'TP'}</td>` : ''}</tr>`;
      }).join('');
      const usedRules = S.rules.filter(r => S.alerts.some(a => a.ruleId === r.id));
      return `<div class="grid"><div class="kpis" style="grid-template-columns:repeat(4,1fr)">
        <button class="kpi" data-act="alStatus" data-s="open"><b id="n-open">${cnt('open')}</b><span>Open</span></button>
        <button class="kpi" data-act="alStatus" data-s="acknowledged"><b>${cnt('acknowledged')}</b><span>Acknowledged</span></button>
        <button class="kpi" data-act="alStatus" data-s="closed"><b>${cnt('closed')}</b><span>Closed</span></button>
        <div class="kpi" style="cursor:default"><b>${sc.done}/${sc.total}</b><span>Classified <button class="link" data-act="alCheck" ${sc.done ? '' : 'disabled'}>Check my triage</button></span></div></div>
      ${S.al.checked ? `<div class="note" id="triage-score">${sc.right} of ${sc.done} classifications match the lab answer. Turn on Lab answers to compare each alert.</div>` : ''}
      <div class="card"><div class="row" style="margin-bottom:8px">
        ${select('sev', 'Severity', [['', 'All'], ['high', 'High'], ['medium', 'Medium'], ['low', 'Low']], p.sev)}
        ${select('status', 'Status', [['', 'All']].concat(STAT.map(s => [s, s])), p.status)}
        ${select('rule', 'Rule', [['', 'All']].concat(usedRules.map(r => [r.id, r.name])), p.rule)}
        ${select('cls', 'Classification', [['', 'All'], ['none', 'Unclassified']].concat(CLS.slice(1)), p.cls)}
        ${p.tech ? `<span class="pill">${esc(p.tech)} ${esc(MITRE[p.tech] || '')} <button class="ib" data-act="alClearTech" aria-label="Clear technique filter">×</button></span>` : ''}
        <input type="search" data-inp="alSearch" value="${esc(S.al.search)}" placeholder="Search alerts" aria-label="Search alerts"><span class="sp"></span>
        <span class="small muted"><span id="alert-count">${rows.length}</span> of ${S.alerts.length} alerts</span></div>
        <div class="row" style="margin-bottom:8px"><span class="small muted">${S.al.sel.size} selected</span><button class="btn sm" data-act="alBulk" data-s="acknowledged" ${S.al.sel.size ? '' : 'disabled'}>Acknowledge</button><button class="btn sm" data-act="alBulk" data-s="closed" ${S.al.sel.size ? '' : 'disabled'}>Close</button><button class="btn sm" data-act="alBulk" data-s="open" ${S.al.sel.size ? '' : 'disabled'}>Reopen</button><button class="btn sm" data-act="alAll">Select all shown</button></div>
        <div style="overflow:auto"><table class="t"><thead><tr><th></th><th>Time</th><th>Rule</th><th>Severity</th><th>Entity</th><th>Reason</th><th>Status</th><th>Assignee</th><th>Classification</th>${S.answers ? '<th>Answer</th>' : ''}</tr></thead>
        <tbody>${body || '<tr><td colspan="10"><div class="empty">No alerts match these filters. Clear a filter, widen the window or enable more rules.</div></td></tr>'}</tbody></table></div></div></div>`;
    },
  };

  function showAlert(id) {
    const a = S.alerts.find(x => x.id === id);
    if (!a) return;
    S.flyAlert = id; S.flyEvent = null;
    const st = alertState(id), rule = S.rules.find(r => r.id === a.ruleId), first = BY[a.eventIds[0]];
    const crossed = a.crossedBy ? BY[a.crossedBy] : null;
    const evs = a.eventIds.slice(0, 40).map(i => {
      const e = BY[i];
      const what = e['process.command_line'] || e['file.path'] || `${e['source.ip']}:${e['source.port']} → ${e['destination.ip']}:${e['destination.port']}`;
      return `<tr class="click" data-act="openEvent" data-id="${esc(i)}"><td class="mono small">${hms(e._t)}</td><td class="mono small">${esc(e['process.name'] || '')}</td><td class="mono small" style="overflow-wrap:anywhere">${esc(what)}</td></tr>`;
    }).join('');
    flyout(`<div class="fhead"><h2>${esc(a.ruleName)}</h2><button class="btn sm" data-act="closeFly">Close</button></div>
      <span class="simtag">${esc(App.D.label)}</span>
      <dl class="kv"><dt>Severity</dt><dd class="sev ${a.severity}">${esc(a.severity)}</dd><dt>Fired</dt><dd>${esc(full(a.t))} UTC</dd><dt>Entity</dt><dd class="mono">${esc(a.entity)}</dd><dt>Reason</dt><dd>${esc(a.reason)}</dd>
      ${crossed ? `<dt>Crossed by</dt><dd class="mono">${esc(crossed['process.name'] || crossed['destination.ip'] || '')} (${esc(docId(crossed))})</dd>` : ''}
      <dt>ATT&amp;CK</dt><dd>${a.mitre.map(m => `<span class="pill" title="${esc(MITRE[m] || '')}">${esc(m)}</span>`).join(' ')}</dd><dt>Fidelity</dt><dd>${esc(rule ? rule.fidelity : '')}</dd></dl>
      <div class="sec"><h3>Triage</h3><div class="row"><label class="small muted">Status <select data-chg="alSet" data-k="status" data-id="${esc(id)}">${STAT.map(s => `<option ${s === st.status ? 'selected' : ''}>${s}</option>`).join('')}</select></label>
        <label class="small muted">Classification <select id="al-cls" data-chg="alSet" data-k="classification" data-id="${esc(id)}">${CLS.map(([v, l]) => `<option value="${v}" ${v === st.classification ? 'selected' : ''}>${l}</option>`).join('')}</select></label>
        <label class="small muted">Assignee <input type="text" style="width:110px" value="${esc(st.assignee)}" data-chg="alSet" data-k="assignee" data-id="${esc(id)}"></label></div></div>
      <div class="sec"><h3>Investigate</h3><div class="row">
        <button class="btn sm" data-act="alDiscover" data-id="${esc(id)}">Open in Discover</button>
        ${first['process.pid'] ? `<button class="btn sm" data-act="toTree" data-pid="${first['process.pid']}">Process tree</button>` : ''}
        <button class="btn sm" data-act="toTimeline" data-id="${esc(a.eventIds[0])}">Timeline</button>
        <button class="btn sm" data-act="alRule" data-id="${esc(a.ruleId)}">View rule</button></div></div>
      <div class="sec"><h3>Matched events (${a.eventIds.length})</h3><div style="max-height:220px;overflow:auto"><table class="t"><tbody>${evs}</tbody></table></div>${a.eventIds.length > 40 ? `<p class="tiny muted">First 40 shown.</p>` : ''}</div>
      <div class="sec"><h3>Analyst notes</h3>${st.notes.map(n => `<p class="small" style="margin:3px 0;border-left:2px solid var(--line2);padding-left:7px">${esc(n)}</p>`).join('')}
        <textarea id="al-note" class="in" style="width:100%;height:54px" aria-label="Add a note" placeholder="What did you find?"></textarea><button class="btn sm" style="margin-top:4px" data-act="alNote" data-id="${esc(id)}">Add note</button></div>
      <div class="sec"><h3>False-positive guidance</h3><p class="small muted" style="margin:0">${esc(rule ? rule.falsePositives : '')}</p></div>
      ${S.answers ? `<div class="sec note">Lab answer: <b>${a.truth === 'false-positive' ? 'false positive' : 'true positive (benign simulation of attacker behaviour)'}</b>. Report event IDs: ${a.eventIds.slice(0, 6).map(esc).join(', ')}${a.eventIds.length > 6 ? ' …' : ''}</div>` : ''}`);
  }
  chg.alFilter = el => { const p = Object.assign({}, S.params); delete p.from; delete p.to; if (el.value) p[el.dataset.k] = el.value; else delete p[el.dataset.k]; go('alerts', p); };
  chg.alSel = (el, e) => { e.stopPropagation(); if (el.checked) S.al.sel.add(el.dataset.id); else S.al.sel.delete(el.dataset.id); render(); };
  chg.alSet = el => { setAlertState(el.dataset.id, { [el.dataset.k]: el.value }); if (S.route === 'alerts' || S.route === 'overview') render(); };
  inp.alSearch = el => {
    S.al.search = el.value;
    const pos = el.selectionStart; render();
    const n = document.querySelector('[data-inp="alSearch"]'); n.focus(); n.setSelectionRange(pos, pos);
  };
  Object.assign(act, {
    showAlert: (el, e) => { if (e.target.closest('input')) return; showAlert(el.dataset.id); },
    showAlertById: id => showAlert(id),
    alStatus: el => go('alerts', { status: el.dataset.s }),
    alClearTech() { const p = Object.assign({}, S.params); delete p.tech; delete p.from; delete p.to; go('alerts', p); },
    alAll() { list().forEach(a => S.al.sel.add(a.id)); render(); },
    alBulk(el) { const n = S.al.sel.size; S.al.sel.forEach(id => setAlertState(id, { status: el.dataset.s })); S.al.sel.clear(); toast(`${n} ${n === 1 ? 'alert' : 'alerts'} set to ${esc(el.dataset.s)}.`); render(); },
    alCheck() { S.al.checked = true; render(); },
    alDiscover(el) {
      const a = S.alerts.find(x => x.id === el.dataset.id), rule = S.rules.find(r => r.id === a.ruleId), t = a.eventIds.map(i => BY[i]._t);
      App.closeFlyout(); S.from = Math.floor((Math.min(...t) - 60000) / 1000) * 1000; S.to = Math.ceil((Math.max(...t) + 60000) / 1000) * 1000;
      S.views.discover.open(rule.kql.replace(/\s+/g, ' '));
    },
    alRule: el => { App.closeFlyout(); go('rules/' + encodeURIComponent(el.dataset.id)); },
    alNote(el) {
      const t = document.getElementById('al-note').value.trim();
      if (!t) return;
      const id = el.dataset.id;
      setAlertState(id, { notes: alertState(id).notes.concat(t) });
      showAlert(id);
    },
  });
})();
